import React, { forwardRef } from 'react';

import Colors from '@dynatrace/strato-design-tokens/colors';
import typography from '@dynatrace/strato-design-tokens/typography';

import {
  getTextWidth,
  _getTextHeight as getTextHeight,
} from '../../../../../../typography/utils.js';
import { useFormatter } from '../context/FormatterContext.js';
import { useOrientation } from '../context/RangeLegendOrientationContext.js';
import { getHorizontalLabelPosition } from '../functions/get-horizontal-label-position.js';
import { getVerticalLabelPosition } from '../functions/get-vertical-label-position.js';
import { LabelAlignment } from '../types/range-legend.internal.js';

interface RangeLegendItemLabelProps {
  startPosition: number;
  itemSegmentSize: number;
  text: string;
  hidden?: boolean;
  alignment?: LabelAlignment;
}

const LABEL_FONT_SIZE = typography.Text.Small.Default.Size;
const LABEL_FONT_COLOR = Colors.Text.Neutral.Subdued;
const ItemFontStyles = {
  fontSize: LABEL_FONT_SIZE,
  fontFamily: typography.Text.Small.Default.Family,
};
export const RangeLegendItemLabel = forwardRef<
  SVGTextElement,
  RangeLegendItemLabelProps
>((props, forwardedRef) => {
  const {
    startPosition,
    itemSegmentSize,
    text,
    hidden = false,
    alignment = 'start',
  } = props;
  const { orientation } = useOrientation();
  const { formatter } = useFormatter();
  const formattedText = formatter(Number(text));

  const labelTextWidth = getTextWidth(formattedText, ItemFontStyles);
  const labelTextHeight = getTextHeight(formattedText, ItemFontStyles);

  const { labelPositionX, labelPositionY } =
    orientation === 'horizontal'
      ? getHorizontalLabelPosition(
          labelTextWidth,
          startPosition,
          itemSegmentSize,
          alignment,
        )
      : getVerticalLabelPosition(
          labelTextHeight,
          startPosition,
          itemSegmentSize,
          alignment,
        );

  return (
    <text
      data-testid="range-legend-item-label"
      ref={forwardedRef}
      x={labelPositionX}
      y={labelPositionY}
      fontSize={LABEL_FONT_SIZE}
      fill={LABEL_FONT_COLOR}
      style={{ visibility: hidden ? 'hidden' : 'visible' }}
    >
      {formattedText}
    </text>
  );
});
